mapper.select:
SELECT variant_id AS variantId,
       holdout_value AS holdoutValue,
       bucket_no AS bucketNo,
       assigned_at AS assignedAt
FROM mk_experiment_assignment
WHERE tenant_id = #{tenantId}
  AND experiment_id = #{experimentId}
  AND version_no = #{version}
  AND randomization_unit = #{unit}

SELECT event_id
FROM mk_fact
WHERE tenant_id = #{tenantId}
  AND correction_root_id = #{correctionRootId}
  AND corrected_value = FALSE
FOR UPDATE

SELECT COUNT(*)
FROM mk_fact
WHERE tenant_id = #{tenantId} AND correction_root_id = #{correctionRootId}

SELECT ingested_at AS ingestedAt, payload_hash AS payloadHash
FROM mk_fact
WHERE tenant_id = #{tenantId} AND event_id = #{eventId}

SELECT partition_count
FROM mk_projection_watermark_config
WHERE tenant_id = #{tenantId} AND projection_name = #{projectionName}

SELECT source_offset AS sourceOffset,
       complete_through_epoch_ms AS completeThroughEpochMillis
FROM mk_projection_partition_watermark
WHERE tenant_id = #{tenantId}
  AND projection_name = #{projectionName}
  AND partition_id = #{partitionId}
FOR UPDATE

mapper.update:
UPDATE mk_projection_partition_watermark
SET source_offset = #{sourceOffset},
    complete_through_epoch_ms = #{completeThroughEpochMillis},
    updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId}
  AND projection_name = #{projectionName}
  AND partition_id = #{partitionId}

mapper.select:
SELECT definition_json AS definitionJson, state_name AS stateName, created_at AS createdAt
FROM mk_experiment
WHERE tenant_id = #{tenantId} AND experiment_id = #{experimentId} AND version_no = #{version}

mapper.update:
UPDATE mk_attribution_recompute_lock
SET updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId}

mapper.select:
SELECT variant_id AS variantId, COUNT(*) AS countValue
FROM mk_fact
WHERE tenant_id = #{tenantId}
  AND fact_type = 'EXPOSURE'
  AND corrected_value = FALSE
  AND experiment_id = #{experimentId}
  AND experiment_version = #{version}
GROUP BY variant_id

mapper.update:
UPDATE mk_experiment
SET state_name = 'PAUSED_SRM'
WHERE tenant_id = #{tenantId} AND experiment_id = #{experimentId} AND version_no = #{version}

mapper.select:
SELECT 
FROM mk_decision_trace
WHERE tenant_id = #{tenantId}
  AND request_id = #{requestId}
  AND (expires_at > #{now} OR legal_hold = TRUE)
LIMIT 1

mapper.update:
UPDATE mk_measurement_command
SET state_name = 'COMPLETED', response_json = #{responseJson}
WHERE tenant_id = #{tenantId} AND command_id = #{commandId}

mapper.select:
SELECT payload_hash
FROM mk_dashboard_projection_delta
WHERE source_topic = #{topic} AND source_partition = #{partition} AND source_offset = #{offset}
